    CreateEnvironmentOperationInput.add_member(:execution_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: IamRoleArn, location_name: 'ExecutionRoleArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the execution role for your environment. An execution role is an Amazon Web Services Identity and Access Management (IAM) role that grants MWAA permission to access Amazon Web Services services and resources used by your environment. For example, <code>arn:aws:iam::123456789:role/my-execution-role</code>. For more information, see <a href=\"https://docs.aws.amazon.com/mwaa/latest/userguide/mwaa-create-role.html\">Amazon MWAA Execution role</a>.</p>", "smithy.api#required" => {}}))
    CreateEnvironmentOperationInput.add_member(:source_bucket_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: S3BucketArn, location_name: 'SourceBucketArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the Amazon S3 bucket where your DAG code and supporting files are stored. For example, <code>arn:aws:s3:::my-airflow-bucket-unique-name</code>. For more information, see <a href=\"https://docs.aws.amazon.com/mwaa/latest/userguide/mwaa-s3-bucket.html\">Create an Amazon S3 bucket for Amazon MWAA</a>.</p>", "smithy.api#required" => {}}))
    CreateEnvironmentOperationInput.add_member(:dag_s3_path, Smithy::Schema::Shapes::ShapeRef.new(shape: RelativePath, location_name: 'DagS3Path', traits: {"smithy.api#documentation" => "<p>The relative path to the DAGs folder on your Amazon S3 bucket. For example, <code>dags</code>. For more information, see <a href=\"https://docs.aws.amazon.com/mwaa/latest/userguide/configuring-dag-folder.html\">Adding or updating DAGs</a>.</p>", "smithy.api#required" => {}}))
    CreateEnvironmentOperationInput.add_member(:network_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: NetworkConfiguration, location_name: 'NetworkConfiguration', traits: {"smithy.api#documentation" => "<p>The VPC networking components used to secure and enable network traffic between the Amazon Web Services resources for your environment. For more information, see <a href=\"https://docs.aws.amazon.com/mwaa/latest/userguide/networking-about.html\">About networking on Amazon MWAA</a>.</p>", "smithy.api#required" => {}}))
    CreateEnvironmentOperationInput.add_member(:plugins_s3_path, Smithy::Schema::Shapes::ShapeRef.new(shape: RelativePath, location_name: 'PluginsS3Path', traits: {"smithy.api#documentation" => "<p>The relative path to the <code>plugins.zip</code> file on your Amazon S3 bucket. For example, <code>plugins.zip</code>. If specified, then the <code>plugins.zip</code> version is required. For more information, see <a href=\"https://docs.aws.amazon.com/mwaa/latest/userguide/configuring-dag-import-plugins.html\">Installing custom plugins</a>.</p>"}))
    CreateEnvironmentOperationInput.add_member(:plugins_s3_object_version, Smithy::Schema::Shapes::ShapeRef.new(shape: S3ObjectVersion, location_name: 'PluginsS3ObjectVersion', traits: {"smithy.api#documentation" => "<p>The version of the plugins.zip file on your Amazon S3 bucket. You must specify a version each time a plugins.zip file is updated. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonS3/latest/userguide/versioning-workflows.html\">How S3 Versioning works</a>.</p>"}))
    CreateEnvironmentOperationInput.add_member(:requirements_s3_path, Smithy::Schema::Shapes::ShapeRef.new(shape: RelativePath, location_name: 'RequirementsS3Path', traits: {"smithy.api#documentation" => "<p>The relative path to the <code>requirements.txt</code> file on your Amazon S3 bucket. For example, <code>requirements.txt</code>. If specified, then a version is required. For more information, see <a href=\"https://docs.aws.amazon.com/mwaa/latest/userguide/working-dags-dependencies.html\">Installing Python dependencies</a>.</p>"}))
    CreateEnvironmentOperationInput.add_member(:requirements_s3_object_version, Smithy::Schema::Shapes::ShapeRef.new(shape: S3ObjectVersion, location_name: 'RequirementsS3ObjectVersion', traits: {"smithy.api#documentation" => "<p>The version of the <code>requirements.txt</code> file on your Amazon S3 bucket. You must specify a version each time a requirements.txt file is updated. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonS3/latest/userguide/versioning-workflows.html\">How S3 Versioning works</a>.</p>"}))
    CreateEnvironmentOperationInput.add_member(:startup_script_s3_path, Smithy::Schema::Shapes::ShapeRef.new(shape: RelativePath, location_name: 'StartupScriptS3Path', traits: {"smithy.api#documentation" => "<p>The relative path to the startup shell script in your Amazon S3 bucket. For example, <code>s3://mwaa-environment/startup.sh</code>.</p>\n         <p>\n            Amazon MWAA runs the script as your environment starts, and before running the Apache Airflow process.\n            You can use this script to install dependencies, modify Apache Airflow configuration options, and set environment variables. For more information, see\n            <a href=\"https://docs.aws.amazon.com/mwaa/latest/userguide/using-startup-script.html\">Using a startup script</a>.\n        </p>"}))
    CreateEnvironmentOperationInput.add_member(:startup_script_s3_object_version, Smithy::Schema::Shapes::ShapeRef.new(shape: S3ObjectVersion, location_name: 'StartupScriptS3ObjectVersion', traits: {"smithy.api#documentation" => "<p>The version of the startup shell script in your Amazon S3 bucket. You must specify the <a href=\"https://docs.aws.amazon.com/AmazonS3/latest/userguide/versioning-workflows.html\">version ID</a> that Amazon S3 assigns to the file\n            every time you update the script.\n        </p>\n         <p>\n            Version IDs are Unicode, UTF-8 encoded, URL-ready, opaque strings that are no more than 1,024 bytes long. The following is an example:\n        </p>\n         <p>\n            <code>3sL4kqtJlcpXroDTDmJ+rmSpXd3dIbrHY+MTRCxf3vjVBH40Nr8X8gdRQBpUMLUo</code>\n         </p>\n         <p>\n            For more information, see <a href=\"https://docs.aws.amazon.com/mwaa/latest/userguide/using-startup-script.html\">Using a startup script</a>.\n        </p>"}))
    CreateEnvironmentOperationInput.add_member(:airflow_configuration_options, Smithy::Schema::Shapes::ShapeRef.new(shape: AirflowConfigurationOptions, location_name: 'AirflowConfigurationOptions', traits: {"smithy.api#documentation" => "<p>A list of key-value pairs containing the Apache Airflow configuration options you want to attach to your environment. For more information, see <a href=\"https://docs.aws.amazon.com/mwaa/latest/userguide/configuring-env-variables.html\">Apache Airflow configuration options</a>.</p>"}))
    CreateEnvironmentOperationInput.add_member(:environment_class, Smithy::Schema::Shapes::ShapeRef.new(shape: EnvironmentClass, location_name: 'EnvironmentClass', traits: {"smithy.api#documentation" => "<p>The environment class type. Valid values: <code>mw1.micro</code>, <code>mw1.small</code>, <code>mw1.medium</code>, <code>mw1.large</code>, <code>mw1.xlarge</code>, and <code>mw1.2xlarge</code>. For more information, see <a href=\"https://docs.aws.amazon.com/mwaa/latest/userguide/environment-class.html\">Amazon MWAA environment class</a>.</p>"}))
    CreateEnvironmentOperationInput.add_member(:max_workers, Smithy::Schema::Shapes::ShapeRef.new(shape: MaxWorkers, location_name: 'MaxWorkers', traits: {"smithy.api#documentation" => "<p>The maximum number of workers that you want to run in your environment. MWAA scales the number of Apache Airflow workers up to the number you specify in the <code>MaxWorkers</code> field. For example, <code>20</code>. When there are no more tasks running, and no more in the queue, MWAA disposes of the extra workers leaving the one worker that is included with your environment, or the number you specify in <code>MinWorkers</code>.</p>"}))
    CreateEnvironmentOperationInput.add_member(:kms_key, Smithy::Schema::Shapes::ShapeRef.new(shape: KmsKey, location_name: 'KmsKey', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services Key Management Service (KMS) key to encrypt the data in your environment. You can use an Amazon Web Services owned CMK, or a Customer managed CMK (advanced). For more information, see <a href=\"https://docs.aws.amazon.com/mwaa/latest/userguide/create-environment.html\">Create an Amazon MWAA environment</a>.</p>"}))
    CreateEnvironmentOperationInput.add_member(:airflow_version, Smithy::Schema::Shapes::ShapeRef.new(shape: AirflowVersion, location_name: 'AirflowVersion', traits: {"smithy.api#documentation" => "<p>The Apache Airflow version for your environment. If no value is specified, it defaults to the latest version.\n            For more information, see <a href=\"https://docs.aws.amazon.com/mwaa/latest/userguide/airflow-versions.html\">Apache Airflow versions on Amazon Managed Workflows for Apache Airflow (Amazon MWAA)</a>.</p>\n         <p>Valid values: <code>1.10.12</code>, <code>2.0.2</code>, <code>2.2.2</code>,\n                <code>2.4.3</code>, <code>2.5.1</code>, <code>2.6.3</code>, <code>2.7.2</code>,\n            <code>2.8.1</code>, <code>2.9.2</code>, <code>2.10.1</code>, and <code>2.10.3</code>.</p>"}))
    CreateEnvironmentOperationInput.add_member(:logging_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: LoggingConfigurationInput, location_name: 'LoggingConfiguration', traits: {"smithy.api#documentation" => "<p>Defines the Apache Airflow logs to send to CloudWatch Logs.</p>"}))
    CreateEnvironmentOperationInput.add_member(:weekly_maintenance_window_start, Smithy::Schema::Shapes::ShapeRef.new(shape: WeeklyMaintenanceWindowStart, location_name: 'WeeklyMaintenanceWindowStart', traits: {"smithy.api#documentation" => "<p>The day and time of the week in Coordinated Universal Time (UTC) 24-hour standard time to start weekly maintenance updates of your environment in the following format: <code>DAY:HH:MM</code>. For example: <code>TUE:03:30</code>. You can specify a start time in 30 minute increments only.</p>"}))
    CreateEnvironmentOperationInput.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagMap, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>The key-value tag pairs you want to associate to your environment. For example, <code>\"Environment\": \"Staging\"</code>. For more information, see <a href=\"https://docs.aws.amazon.com/general/latest/gr/aws_tagging.html\">Tagging Amazon Web Services resources</a>.</p>"}))
    CreateEnvironmentOperationInput.add_member(:webserver_access_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: WebserverAccessMode, location_name: 'WebserverAccessMode', traits: {"smithy.api#documentation" => "<p>Defines the access mode for the Apache Airflow <i>web server</i>. For more information, see <a href=\"https://docs.aws.amazon.com/mwaa/latest/userguide/configuring-networking.html\">Apache Airflow access modes</a>.</p>"}))
    CreateEnvironmentOperationInput.add_member(:min_workers, Smithy::Schema::Shapes::ShapeRef.new(shape: MinWorkers, location_name: 'MinWorkers', traits: {"smithy.api#documentation" => "<p>The minimum number of workers that you want to run in your environment. MWAA scales the number of Apache Airflow workers up to the number you specify in the <code>MaxWorkers</code> field. When there are no more tasks running, and no more in the queue, MWAA disposes of the extra workers leaving the worker count you specify in the <code>MinWorkers</code> field. For example, <code>2</code>.</p>"}))
    CreateEnvironmentOperationInput.add_member(:schedulers, Smithy::Schema::Shapes::ShapeRef.new(shape: Schedulers, location_name: 'Schedulers', traits: {"smithy.api#documentation" => "<p>The number of Apache Airflow schedulers to run in your environment. Valid values:</p>\n         <ul>\n            <li>\n               <p>v2 - For environments larger than mw1.micro, accepts values from\n                        <code>2</code> to <code>5</code>. Defaults to <code>2</code> for all\n                    environment sizes except mw1.micro, which defaults to <code>1</code>.</p>\n            </li>\n            <li>\n               <p>v1 - Accepts <code>1</code>.</p>\n            </li>\n         </ul>"}))
    CreateEnvironmentOperationInput.add_member(:endpoint_management, Smithy::Schema::Shapes::ShapeRef.new(shape: EndpointManagement, location_name: 'EndpointManagement', traits: {"smithy.api#documentation" => "<p>Defines whether the VPC endpoints configured for the environment are created, and managed, by the customer or by Amazon MWAA. If set to <code>SERVICE</code>, Amazon MWAA will create and manage the required VPC endpoints in\n        your VPC. If set to <code>CUSTOMER</code>, you must create, and manage, the VPC endpoints for your VPC. If you choose to create an environment in a shared VPC, you must set this value to <code>CUSTOMER</code>.\n        In a shared VPC deployment, the environment will remain in <code>PENDING</code> status until you create the VPC endpoints. If you do not take action to\n            create the endpoints within 72 hours, the status will change to <code>CREATE_FAILED</code>. You can delete the failed environment and create a new one.</p>"}))
    CreateEnvironmentOperationInput.add_member(:min_webservers, Smithy::Schema::Shapes::ShapeRef.new(shape: MinWebservers, location_name: 'MinWebservers', traits: {"smithy.api#documentation" => "<p>\n            The minimum number of web servers that you want to run in your environment.\n            Amazon MWAA scales the number of Apache Airflow web servers up to the number you specify for <code>MaxWebservers</code>\n            when you interact with your Apache Airflow environment using Apache Airflow REST API, or\n            the Apache Airflow CLI. As the transaction-per-second rate, and the network load, decrease,\n            Amazon MWAA disposes of the additional web servers, and scales down to the number set in <code>MinxWebserers</code>.\n        </p>\n         <p>Valid values: For environments larger than mw1.micro, accepts values from\n                <code>2</code> to <code>5</code>. Defaults to <code>2</code> for all environment\n            sizes except mw1.micro, which defaults to <code>1</code>.</p>"}))
    CreateEnvironmentOperationInput.add_member(:max_webservers, Smithy::Schema::Shapes::ShapeRef.new(shape: MaxWebservers, location_name: 'MaxWebservers', traits: {"smithy.api#documentation" => "<p>\n            The maximum number of web servers that you want to run in your environment.\n            Amazon MWAA scales the number of Apache Airflow web servers up to the number you specify for <code>MaxWebservers</code>\n            when you interact with your Apache Airflow environment using Apache Airflow REST API, or\n            the Apache Airflow CLI. For example, in scenarios where your workload requires network calls to the Apache Airflow REST API with a high transaction-per-second (TPS)\n            rate, Amazon MWAA will increase the number of web servers up to the number set in <code>MaxWebserers</code>. As TPS rates decrease\n            Amazon MWAA disposes of the additional web servers, and scales down to the number set in <code>MinxWebserers</code>.\n        </p>\n         <p>Valid values: For environments larger than mw1.micro, accepts values from\n                <code>2</code> to <code>5</code>. Defaults to <code>2</code> for all environment\n            sizes except mw1.micro, which defaults to <code>1</code>.</p>"}))
    CreateEnvironmentOperationInput.type = Types::CreateEnvironmentOperationInput
    CreateEnvironmentOperationOutput.add_member(:arn, Smithy::Schema::Shapes::ShapeRef.new(shape: EnvironmentArn, location_name: 'Arn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) returned in the response for the environment.</p>"}))
    CreateEnvironmentOperationOutput.type = Types::CreateEnvironmentOperationOutput
