    CreateWebLoginTokenOutput.add_member(:web_server_hostname, Smithy::Schema::Shapes::ShapeRef.new(shape: Hostname, location_name: 'WebServerHostname', traits: {"smithy.api#documentation" => "<p>The Airflow web server hostname for the environment.</p>"}))
    CreateWebLoginTokenOutput.add_member(:iam_identity, Smithy::Schema::Shapes::ShapeRef.new(shape: IamIdentity, location_name: 'IamIdentity', traits: {"smithy.api#documentation" => "<p>The name of the IAM identity creating the web login token. This might be an IAM user, or an assumed or federated identity. For example, <code>assumed-role/Admin/your-name</code>.</p>"}))
    CreateWebLoginTokenOutput.add_member(:airflow_identity, Smithy::Schema::Shapes::ShapeRef.new(shape: AirflowIdentity, location_name: 'AirflowIdentity', traits: {"smithy.api#documentation" => "<p>The user name of the Apache Airflow identity creating the web login token.</p>"}))
