    Dimension.add_member(:value, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::String, location_name: 'Value', traits: {"smithy.api#documentation" => "<p>\n            <b>Internal only</b>. The value of the dimension.</p>", "smithy.api#required" => {}}))
