    Environment.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: EnvironmentName, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The name of the Amazon MWAA environment. For example, <code>MyMWAAEnvironment</code>.</p>"}))
    Environment.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: EnvironmentStatus, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>The status of the Amazon MWAA environment.</p>\n         <p>Valid values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>CREATING</code> - Indicates the request to create the environment is in progress.</p>\n            </li>\n            <li>\n               <p>\n                  <code>CREATING_SNAPSHOT</code> - Indicates the request to update environment details, or upgrade the environment version, is in progress and Amazon MWAA is creating a storage volume snapshot of the Amazon RDS\n                    database cluster associated with the environment. A database snapshot is a backup created at a specific point in time. Amazon MWAA uses snapshots to recover environment metadata if the process to update or upgrade\n                    an environment fails.</p>\n            </li>\n            <li>\n               <p>\n                  <code>CREATE_FAILED</code> - Indicates the request to create the environment failed, and the environment could not be created.</p>\n            </li>\n            <li>\n               <p>\n                  <code>AVAILABLE</code> - Indicates the request was successful and the environment is ready to use.</p>\n            </li>\n            <li>\n               <p>\n                  <code>PENDING</code> - Indicates the request was successful, but the process to create the environment is paused until you create the required\n                    VPC endpoints in your VPC. After you create the VPC endpoints, the process resumes.</p>\n            </li>\n            <li>\n               <p>\n                  <code>UPDATING</code> - Indicates the request to update the environment is in progress.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ROLLING_BACK</code> - Indicates the request to update environment details, or upgrade the environment version, failed and Amazon MWAA is restoring the environment using the latest storage volume snapshot.</p>\n            </li>\n            <li>\n               <p>\n                  <code>DELETING</code> - Indicates the request to delete the environment is in progress.</p>\n            </li>\n            <li>\n               <p>\n                  <code>DELETED</code> - Indicates the request to delete the environment is complete, and the environment has been deleted.</p>\n            </li>\n            <li>\n               <p>\n                  <code>UNAVAILABLE</code> - Indicates the request failed, but the environment did not return to its previous state and is not stable.</p>\n            </li>\n            <li>\n               <p>\n                  <code>UPDATE_FAILED</code> - Indicates the request to update the environment failed, and the environment was restored to its previous state successfully and is ready to use.</p>\n            </li>\n            <li>\n               <p>\n                  <code>MAINTENANCE</code> - Indicates that the environment is undergoing maintenance. Depending on the type of work Amazon MWAA is performing,\n              your environment might become unavailable during this process. After all operations are done, your environment will return to its status prior to mainteneace operations.\n            </p>\n            </li>\n         </ul>\n         <p>We recommend reviewing our troubleshooting guide for a list of common errors and their solutions. For more information, see <a href=\"https://docs.aws.amazon.com/mwaa/latest/userguide/troubleshooting.html\">Amazon MWAA troubleshooting</a>.</p>"}))
    Environment.add_member(:arn, Smithy::Schema::Shapes::ShapeRef.new(shape: EnvironmentArn, location_name: 'Arn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the Amazon MWAA environment.</p>"}))
    Environment.add_member(:created_at, Smithy::Schema::Shapes::ShapeRef.new(shape: CreatedAt, location_name: 'CreatedAt', traits: {"smithy.api#documentation" => "<p>The day and time the environment was created.</p>"}))
    Environment.add_member(:webserver_url, Smithy::Schema::Shapes::ShapeRef.new(shape: WebserverUrl, location_name: 'WebserverUrl', traits: {"smithy.api#documentation" => "<p>The Apache Airflow <i>web server</i> host name for the Amazon MWAA environment. For more information, see <a href=\"https://docs.aws.amazon.com/mwaa/latest/userguide/access-airflow-ui.html\">Accessing the Apache Airflow UI</a>.</p>"}))
    Environment.add_member(:execution_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: IamRoleArn, location_name: 'ExecutionRoleArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the execution role in IAM that allows MWAA to access Amazon Web Services resources in your environment. For example, <code>arn:aws:iam::123456789:role/my-execution-role</code>. For more information, see <a href=\"https://docs.aws.amazon.com/mwaa/latest/userguide/mwaa-create-role.html\">Amazon MWAA Execution role</a>.</p>"}))
    Environment.add_member(:service_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: IamRoleArn, location_name: 'ServiceRoleArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) for the service-linked role of the environment. For more information, see <a href=\"https://docs.aws.amazon.com/mwaa/latest/userguide/mwaa-slr.html\">Amazon MWAA Service-linked role</a>.</p>"}))
    Environment.add_member(:kms_key, Smithy::Schema::Shapes::ShapeRef.new(shape: KmsKey, location_name: 'KmsKey', traits: {"smithy.api#documentation" => "<p>The KMS encryption key used to encrypt the data in your environment.</p>"}))
    Environment.add_member(:airflow_version, Smithy::Schema::Shapes::ShapeRef.new(shape: AirflowVersion, location_name: 'AirflowVersion', traits: {"smithy.api#documentation" => "<p>The Apache Airflow version on your environment.</p>\n         <p>Valid values: <code>1.10.12</code>, <code>2.0.2</code>, <code>2.2.2</code>,\n                <code>2.4.3</code>, <code>2.5.1</code>, <code>2.6.3</code>, <code>2.7.2</code>,\n            <code>2.8.1</code>, <code>2.9.2</code>, <code>2.10.1</code>, and <code>2.10.3</code>.</p>"}))
    Environment.add_member(:source_bucket_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: S3BucketArn, location_name: 'SourceBucketArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the Amazon S3 bucket where your DAG code and supporting files are stored. For example, <code>arn:aws:s3:::my-airflow-bucket-unique-name</code>. For more information, see <a href=\"https://docs.aws.amazon.com/mwaa/latest/userguide/mwaa-s3-bucket.html\">Create an Amazon S3 bucket for Amazon MWAA</a>.</p>"}))
    Environment.add_member(:dag_s3_path, Smithy::Schema::Shapes::ShapeRef.new(shape: RelativePath, location_name: 'DagS3Path', traits: {"smithy.api#documentation" => "<p>The relative path to the DAGs folder in your Amazon S3 bucket. For example, <code>s3://mwaa-environment/dags</code>. For more information, see <a href=\"https://docs.aws.amazon.com/mwaa/latest/userguide/configuring-dag-folder.html\">Adding or updating DAGs</a>.</p>"}))
    Environment.add_member(:plugins_s3_path, Smithy::Schema::Shapes::ShapeRef.new(shape: RelativePath, location_name: 'PluginsS3Path', traits: {"smithy.api#documentation" => "<p>The relative path to the file in your Amazon S3 bucket. For example, <code>s3://mwaa-environment/plugins.zip</code>. For more information, see <a href=\"https://docs.aws.amazon.com/mwaa/latest/userguide/configuring-dag-import-plugins.html\">Installing custom plugins</a>.</p>"}))
    Environment.add_member(:plugins_s3_object_version, Smithy::Schema::Shapes::ShapeRef.new(shape: S3ObjectVersion, location_name: 'PluginsS3ObjectVersion', traits: {"smithy.api#documentation" => "<p>The version of the <code>plugins.zip</code> file in your Amazon S3 bucket. You must specify the <a href=\"https://docs.aws.amazon.com/AmazonS3/latest/userguide/versioning-workflows.html\">version ID</a> that Amazon S3 assigns to the file.</p>\n         <p>\n            Version IDs are Unicode, UTF-8 encoded, URL-ready, opaque strings that are no more than 1,024 bytes long. The following is an example:\n        </p>\n         <p>\n            <code>3sL4kqtJlcpXroDTDmJ+rmSpXd3dIbrHY+MTRCxf3vjVBH40Nr8X8gdRQBpUMLUo</code>\n         </p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/mwaa/latest/userguide/configuring-dag-import-plugins.html\">Installing custom plugins</a>.</p>"}))
