    Environment.add_member(:requirements_s3_object_version, Smithy::Schema::Shapes::ShapeRef.new(shape: S3ObjectVersion, location_name: 'RequirementsS3ObjectVersion', traits: {"smithy.api#documentation" => "<p>The version of the <code>requirements.txt </code> file on your Amazon S3 bucket. You must specify the <a href=\"https://docs.aws.amazon.com/AmazonS3/latest/userguide/versioning-workflows.html\">version ID</a> that Amazon S3 assigns to the file.</p>\n         <p>\n            Version IDs are Unicode, UTF-8 encoded, URL-ready, opaque strings that are no more than 1,024 bytes long. The following is an example:\n        </p>\n         <p>\n            <code>3sL4kqtJlcpXroDTDmJ+rmSpXd3dIbrHY+MTRCxf3vjVBH40Nr8X8gdRQBpUMLUo</code>\n         </p>\n         <p>\n            For more information, see <a href=\"https://docs.aws.amazon.com/mwaa/latest/userguide/working-dags-dependencies.html\">Installing Python dependencies</a>.\n        </p>"}))
    Environment.add_member(:startup_script_s3_path, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::String, location_name: 'StartupScriptS3Path', traits: {"smithy.api#documentation" => "<p>The relative path to the startup shell script in your Amazon S3 bucket. For example, <code>s3://mwaa-environment/startup.sh</code>.</p>\n         <p>\n            Amazon MWAA runs the script as your environment starts, and before running the Apache Airflow process.\n            You can use this script to install dependencies, modify Apache Airflow configuration options, and set environment variables. For more information, see\n            <a href=\"https://docs.aws.amazon.com/mwaa/latest/userguide/using-startup-script.html\">Using a startup script</a>.\n        </p>"}))
    Environment.add_member(:startup_script_s3_object_version, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::String, location_name: 'StartupScriptS3ObjectVersion', traits: {"smithy.api#documentation" => "<p>The version of the startup shell script in your Amazon S3 bucket. You must specify the <a href=\"https://docs.aws.amazon.com/AmazonS3/latest/userguide/versioning-workflows.html\">version ID</a> that Amazon S3 assigns to the file.</p>\n         <p>\n            Version IDs are Unicode, UTF-8 encoded, URL-ready, opaque strings that are no more than 1,024 bytes long. The following is an example:\n        </p>\n         <p>\n            <code>3sL4kqtJlcpXroDTDmJ+rmSpXd3dIbrHY+MTRCxf3vjVBH40Nr8X8gdRQBpUMLUo</code>\n         </p>\n         <p>\n            For more information, see <a href=\"https://docs.aws.amazon.com/mwaa/latest/userguide/using-startup-script.html\">Using a startup script</a>.\n        </p>"}))
    Environment.add_member(:airflow_configuration_options, Smithy::Schema::Shapes::ShapeRef.new(shape: AirflowConfigurationOptions, location_name: 'AirflowConfigurationOptions', traits: {"smithy.api#documentation" => "<p>A list of key-value pairs containing the Apache Airflow configuration options attached to your environment. For more information, see <a href=\"https://docs.aws.amazon.com/mwaa/latest/userguide/configuring-env-variables.html\">Apache Airflow configuration options</a>.</p>"}))
    Environment.add_member(:environment_class, Smithy::Schema::Shapes::ShapeRef.new(shape: EnvironmentClass, location_name: 'EnvironmentClass', traits: {"smithy.api#documentation" => "<p>The environment class type. Valid values: <code>mw1.micro</code>, <code>mw1.small</code>, <code>mw1.medium</code>, <code>mw1.large</code>, <code>mw1.xlarge</code>, and <code>mw1.2xlarge</code>. For more information, see <a href=\"https://docs.aws.amazon.com/mwaa/latest/userguide/environment-class.html\">Amazon MWAA environment class</a>.</p>"}))
