    Environment.add_member(:weekly_maintenance_window_start, Smithy::Schema::Shapes::ShapeRef.new(shape: WeeklyMaintenanceWindowStart, location_name: 'WeeklyMaintenanceWindowStart', traits: {"smithy.api#documentation" => "<p>The day and time of the week in Coordinated Universal Time (UTC) 24-hour standard time that weekly maintenance updates are scheduled. For example: <code>TUE:03:30</code>.</p>"}))
