    UpdateEnvironmentOperationInput.add_member(:airflow_configuration_options, Smithy::Schema::Shapes::ShapeRef.new(shape: AirflowConfigurationOptions, location_name: 'AirflowConfigurationOptions', traits: {"smithy.api#documentation" => "<p>A list of key-value pairs containing the Apache Airflow configuration options you want to attach to your environment. For more information, see <a href=\"https://docs.aws.amazon.com/mwaa/latest/userguide/configuring-env-variables.html\">Apache Airflow configuration options</a>.</p>"}))
    UpdateEnvironmentOperationInput.add_member(:airflow_version, Smithy::Schema::Shapes::ShapeRef.new(shape: AirflowVersion, location_name: 'AirflowVersion', traits: {"smithy.api#documentation" => "<p>The Apache Airflow version for your environment. To upgrade your environment, specify a newer version of Apache Airflow supported by Amazon MWAA.</p>\n         <p>Before you upgrade an environment, make sure your requirements, DAGs, plugins, and other resources used in your workflows are compatible with the new Apache Airflow version. For more information about updating\n            your resources, see <a href=\"https://docs.aws.amazon.com/mwaa/latest/userguide/upgrading-environment.html\">Upgrading an Amazon MWAA environment</a>.</p>\n         <p>Valid values: <code>1.10.12</code>, <code>2.0.2</code>, <code>2.2.2</code>,\n                <code>2.4.3</code>, <code>2.5.1</code>, <code>2.6.3</code>, <code>2.7.2</code>,\n            <code>2.8.1</code>, <code>2.9.2</code>, <code>2.10.1</code>, and <code>2.10.3</code>.</p>"}))
