    UpdateEnvironmentOperationInput.add_member(:max_workers, Smithy::Schema::Shapes::ShapeRef.new(shape: MaxWorkers, location_name: 'MaxWorkers', traits: {"smithy.api#documentation" => "<p>The maximum number of workers that you want to run in your environment. MWAA scales the number of Apache Airflow workers up to the number you specify in the <code>MaxWorkers</code> field. For example, <code>20</code>. When there are no more tasks running, and no more in the queue, MWAA disposes of the extra workers leaving the one worker that is included with your environment, or the number you specify in <code>MinWorkers</code>.</p>"}))
    UpdateEnvironmentOperationInput.add_member(:min_workers, Smithy::Schema::Shapes::ShapeRef.new(shape: MinWorkers, location_name: 'MinWorkers', traits: {"smithy.api#documentation" => "<p>The minimum number of workers that you want to run in your environment. MWAA scales the number of Apache Airflow workers up to the number you specify in the <code>MaxWorkers</code> field. When there are no more tasks running, and no more in the queue, MWAA disposes of the extra workers leaving the worker count you specify in the <code>MinWorkers</code> field. For example, <code>2</code>.</p>"}))
    UpdateEnvironmentOperationInput.add_member(:max_webservers, Smithy::Schema::Shapes::ShapeRef.new(shape: MaxWebservers, location_name: 'MaxWebservers', traits: {"smithy.api#documentation" => "<p>\n            The maximum number of web servers that you want to run in your environment.\n            Amazon MWAA scales the number of Apache Airflow web servers up to the number you specify for <code>MaxWebservers</code>\n            when you interact with your Apache Airflow environment using Apache Airflow REST API, or\n            the Apache Airflow CLI. For example, in scenarios where your workload requires network calls to the Apache Airflow REST API with a high transaction-per-second (TPS)\n            rate, Amazon MWAA will increase the number of web servers up to the number set in <code>MaxWebserers</code>. As TPS rates decrease\n            Amazon MWAA disposes of the additional web servers, and scales down to the number set in <code>MinxWebserers</code>.\n        </p>\n         <p>Valid values: For environments larger than mw1.micro, accepts values from\n                <code>2</code> to <code>5</code>. Defaults to <code>2</code> for all environment\n            sizes except mw1.micro, which defaults to <code>1</code>.</p>"}))
    UpdateEnvironmentOperationInput.add_member(:min_webservers, Smithy::Schema::Shapes::ShapeRef.new(shape: MinWebservers, location_name: 'MinWebservers', traits: {"smithy.api#documentation" => "<p>\n            The minimum number of web servers that you want to run in your environment.\n            Amazon MWAA scales the number of Apache Airflow web servers up to the number you specify for <code>MaxWebservers</code>\n            when you interact with your Apache Airflow environment using Apache Airflow REST API, or\n            the Apache Airflow CLI. As the transaction-per-second rate, and the network load, decrease,\n            Amazon MWAA disposes of the additional web servers, and scales down to the number set in <code>MinxWebserers</code>.\n        </p>\n         <p>Valid values: For environments larger than mw1.micro, accepts values from\n                <code>2</code> to <code>5</code>. Defaults to <code>2</code> for all environment\n            sizes except mw1.micro, which defaults to <code>1</code>.</p>"}))
    UpdateEnvironmentOperationInput.add_member(:worker_replacement_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: WorkerReplacementStrategy, location_name: 'WorkerReplacementStrategy', traits: {"smithy.api#documentation" => "<p>The worker replacement strategy to use when updating the environment.</p>\n         <p>You can select one of the following strategies:</p>\n         <ul>\n            <li>\n               <p>\n                  <b>Forced -</b> Stops and replaces Apache Airflow workers without waiting for tasks to \n                    complete before an update.</p>\n            </li>\n            <li>\n               <p>\n                  <b>Graceful -</b> Allows Apache Airflow workers to complete running tasks for up to 12 hours during an update before \n                    they're stopped and replaced.</p>\n            </li>\n         </ul>"}))
    UpdateEnvironmentOperationInput.add_member(:network_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: UpdateNetworkConfigurationInput, location_name: 'NetworkConfiguration', traits: {"smithy.api#documentation" => "<p>The VPC networking components used to secure and enable network traffic between the Amazon Web Services resources for your environment. For more information, see <a href=\"https://docs.aws.amazon.com/mwaa/latest/userguide/networking-about.html\">About networking on Amazon MWAA</a>.</p>"}))
