    UpdateEnvironmentOperationInput.add_member(:weekly_maintenance_window_start, Smithy::Schema::Shapes::ShapeRef.new(shape: WeeklyMaintenanceWindowStart, location_name: 'WeeklyMaintenanceWindowStart', traits: {"smithy.api#documentation" => "<p>The day and time of the week in Coordinated Universal Time (UTC) 24-hour standard time to start weekly maintenance updates of your environment in the following format: <code>DAY:HH:MM</code>. For example: <code>TUE:03:30</code>. You can specify a start time in 30 minute increments only.</p>"}))
